import math
def priority(task, state, m=10.0, k=1.0, b=2.0, a=2.0, q=5.0, frac=0.2, guard=1e6, tail=4.0):
    p = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - p
    if task.tenant == 'premium':
        if slack <= 0.0:
            return guard + m * (-slack) / p + task.weight / p
        base = (task.weight / p) * (1.0 + b * wait / p)
        return base * (1.0 + m * math.exp(-slack / (k * mean)))
