import math
def priority(task, state, safety=1.5, k=2.0, age=1.0, m=0.25, mem=0.1, prem=1e6, qmargin=0.02):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    slack_raw = task.due - now - est
    if task.tenant == 'premium':
        margin = safety * max(state.mean_est, est, 1.0) + qmargin * state.queue_len * max(state.mean_est, 1.0)
        if slack_raw <= margin or task.due <= now:
            return prem - max(task.due, now + est)
        tier = m
    else:
        tier = 1.0
    wait = max(0.0, now - task.release)
    slack = max(0.0, slack_raw)
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    age_score = (1.0 + age * wait / est) / est
    if task.tenant == 'premium':
        age_score *= m
    occ = task.resource_need / max(state.capacity, 1e-6)
    return (atc + age_score) / (1.0 + mem * occ)

