def priority(task, state, c=1.0, p=1.0, k=1.5, m=5.0, margin=0.5, mem=0.05, qhi=10.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    mean = max(state.mean_est, 1e-6)
    load = state.queue_len / max(qhi, 1e-6) + state.queue_work / max(state.capacity, 1e-6)
    load = min(load, 20.0)
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        if slack <= 0.0:
            return 1e10 + m * task.weight / est + p * ratio + 1.0 / est
        if slack <= margin * mean:
            return 1e8 + m * task.weight / est + p * ratio + 1.0 / est
        return m * task.weight / est * math.exp(-slack / max(k * mean, 1e-6)) + p * ratio + 1.0 / est
    else:
        guard_thr = c / max(1.0 + 0.15 * load, 1e-6)
        guard = 1e6 if ratio >= guard_thr else 0.0
        return guard + task.weight / est + p * ratio + mem / max(task.resource_need, 1e-6)
