import math
def priority(task, state, k=2.0, m=5.0, b=1.0, alpha=0.3, c=4.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    pressure = 1.0 - state.free / max(state.capacity, 1e-6)
    if pressure < 0.0:
        pressure = 0.0
    if pressure > 1.0:
        pressure = 1.0
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        if slack >= 0.0:
            urgency = math.exp(-slack / (k * mean))
        else:
            urgency = 1.0 + c * (-slack) / mean
        late = max(0.0, state.now - task.due) / mean
        late_factor = 1.0 + c * late
        return m * task.weight / est * urgency * late_factor * (1.0 + 0.2 * wait / est)
    else:
        hrrn = (wait + est) / est
        mem_factor = 1.0 / (max(task.resource_need, 1e-6) ** (alpha * pressure))
        risk = 1.0 + b * max(0.0, wait + est - 2.0 * mean) / mean
        short_boost = 1.0 + pressure * max(0.0, mean - est) / mean
        return task.weight * hrrn * mem_factor * risk * short_boost

